from __future__ import annotations

import json
from decimal import Decimal
from pathlib import Path
from typing import Any

from evidence_kernel.paths import repo_root
from evidence_kernel.schema import validate_instance

from evidence_eval.faults import clean_artifact, inject
from evidence_eval.numbers import format_quantum

GENERATOR_VERSION = "0.1.0"
SEED = 20261103
PROVENANCE = {
    "origin": "synthetic",
    "author": "aeroregu",
    "generator_version": GENERATOR_VERSION,
    "seed": SEED,
    "statement": "Invented benchmark case. Generated by calc, then one fault injector.",
    "label": "ASSUMPTION",
}

FAULTS = (
    "unit_scale",
    "arithmetic",
    "wrong_input",
    "sign",
    "stale_revision",
    "false_coverage",
    "broken_hash",
    "bad_span",
    "outside_validity",
    "missing_input",
)


def build_cases(split: str) -> list[dict[str, Any]]:
    if split == "dev":
        pairs = 2
    elif split == "holdout":
        pairs = 1
    else:
        raise ValueError(split)
    cases: list[dict[str, Any]] = []
    for fault in FAULTS:
        for slot in range(pairs):
            cases.append(_case(split, fault, slot))
    clean_slots = 4 if split == "dev" else 2
    for slot in range(clean_slots):
        cases.append(_case(split, None, slot))
    for case in cases:
        validate_instance("benchmark_case.schema.json", case)
    return cases


def write_split(split: str) -> Path:
    folder = repo_root() / "bench" / split
    folder.mkdir(parents=True, exist_ok=True)
    for stale in folder.glob("*.json"):
        stale.unlink()
    for case in build_cases(split):
        path = folder / f"{case['case_id']}.json"
        path.write_text(json.dumps(case, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if split == "holdout":
        digest = directory_hash(folder)
        (folder / "SHA256.txt").write_text(digest + "\n", encoding="utf-8")
    return folder


def directory_hash(folder: Path) -> str:
    import hashlib

    digest = hashlib.sha256()
    for path in sorted(folder.glob("*.json")):
        digest.update(path.name.encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes().replace(b"\r\n", b"\n"))
        digest.update(b"\0")
    return digest.hexdigest()


def _case(split: str, fault: str | None, slot: int) -> dict[str, Any]:
    method_id, inputs, kind = _parent(fault, slot, split)
    artifact = clean_artifact(method_id, inputs)
    if fault:
        artifact = inject(fault, artifact, slot)
        expected = "abstain" if fault == "missing_input" else f"detect:{fault}"
        faults = [fault]
    else:
        expected = "clean"
        faults = []
    tag = fault or "clean"
    return {
        "case_id": f"{split}-{kind}-{tag}-{slot:02d}",
        "artifact_kind": kind,
        "faults": faults,
        "expected": expected,
        "artifact": artifact,
        "provenance": dict(PROVENANCE),
    }


def _parent(fault: str | None, slot: int, split: str) -> tuple[str, dict[str, Any], str]:
    offset = 0 if split == "dev" else 3
    use_bolt = _use_bolt(fault, slot)
    if use_bolt:
        shear = Decimal("3000") + Decimal(slot + offset)
        if fault == "unit_scale":
            shear = Decimal("3") + Decimal(slot + offset)
        return "bolt_screen", _bolt(shear), "note"
    mass = Decimal("800") + Decimal(slot + offset)
    load = "1.000" if slot % 2 == 0 else "2.000"
    if fault == "unit_scale":
        mass = Decimal("2") + Decimal(slot + offset)
    if fault == "sign":
        load = "1.000" if slot == 0 else "1.500"
        if split == "holdout":
            load = "2.000"
    return "rigid_body_point_mass", _point(mass, load), "matrix"


def _use_bolt(fault: str | None, slot: int) -> bool:
    if fault == "sign":
        return False
    if fault == "unit_scale":
        return slot == 0
    if fault in {"missing_input", "outside_validity", "wrong_input", "arithmetic"}:
        return slot == 0
    if fault is None:
        return slot % 2 == 0
    return slot == 0


def _bolt(shear: Decimal) -> dict[str, Any]:
    return {
        "shear_force_n": format_quantum(shear),
        "tensile_force_n": "4000.000",
        "area_mm2": "80.000",
        "shear_allowable_mpa": "250.000",
        "tensile_allowable_mpa": "250.000",
        "thickness_mm": "5.000",
    }


def _point(mass: Decimal, load_factor: str) -> dict[str, Any]:
    return {
        "mass_kg": format_quantum(mass),
        "gravity_m_s2": "9.810",
        "load_factor": load_factor,
        "altitude_m": "0.000",
        "cg_x_m": "0.000",
        "unit_x_m": ["-2.000", "-1.000", "1.000", "2.000"],
        "unit_operative": [True, True, True, True],
    }
